source .venv/bin/activate && python3 -c "
# Download older BBC news (2022) from HuggingFace for pre-cutoff control
from datasets import load_dataset
try:
    bbc_old = load_dataset('RealTimeData/bbc_news_alltime', split='train', streaming=True)
    # Take a sample
    samples = []
    for i, item in enumerate(bbc_old):
        if item.get('published_date', '') and item['published_date'][:4] in ['2021', '2022']:
            samples.append(item)
            if len(samples) >= 500:
                break
        if i > 50000:
            break
    print(f'Got {len(samples)} pre-cutoff articles')
    if samples:
        print('Sample keys:', list(samples[0].keys()))
        print('Sample date:', samples[0].get('published_date', 'N/A'))
except Exception as e:
    print(f'Error: {e}')
    # Try alternative
    print('Trying alternative approach...')
" 2>&1
